contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0));
        uint beforeRecipientBalance = recipient.balance;
        uint beforeContractBalance = address(c).balance;

        c.getFirstWithdrawalBonus(recipient); if (__ESBMC_reverted()) return;

        uint afterFirstRecipientBalance = recipient.balance;
        uint afterFirstContractBalance = address(c).balance;
        require(afterFirstRecipientBalance >= beforeRecipientBalance);
        require(afterFirstRecipientBalance - beforeRecipientBalance == 100);
        require(beforeContractBalance >= afterFirstContractBalance);
        require(beforeContractBalance - afterFirstContractBalance == 100);

        uint recipientBeforeSecond = recipient.balance;
        uint contractBeforeSecond = address(c).balance;
        bool reverted;
        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && recipient.balance == recipientBeforeSecond && address(c).balance == contractBeforeSecond);
    }

    receive() external payable {}
}

