        try c.getFirstWithdrawalBonus(recipient) {} catch { return; }
        uint afterFirstRecipientBalance = recipient.balance;
        uint afterFirstContractBalance = address(c).balance;
        vm.assume(afterFirstRecipientBalance >= beforeRecipientBalance);
        vm.assume(afterFirstRecipientBalance - beforeRecipientBalance == 100);
